globalCss:
.gallery-dark-card {
  background: #0A0A0A;
  border: 1px solid #2A2A2A;
  border-radius: 0.125rem;
  overflow: hidden;
  transition: all 300ms ease-out;
}
.gallery-dark-card:hover {
  border-color: #4A4A4A;
}
.gallery-dark-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.gallery-dark-image-container {
  overflow: hidden;
  position: relative;
  background: #1A1A1A;
}
.gallery-dark-image-container:hover .gallery-dark-image {
  opacity: 0.9;
  transition: opacity 300ms ease-out;
}
.gallery-dark-caption {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.75rem;
  font-weight: 300;
  line-height: 1.6;
  color: #666666;
  letter-spacing: 0.05em;
}
.gallery-dark-meta {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.625rem;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  font-weight: 300;
  color: #C4956A;
}
.gallery-dark-hairline {
  border: none;
  border-top: 1px solid #2A2A2A;
}
.gallery-dark-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}
@media (min-width: 768px) {
  .gallery-dark-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 1.5rem;
  }
}
.gallery-dark-hero-overlay {
  position: absolute;
  inset: 0;
  background: rgba(10, 10, 10, 0.5);
}
.gallery-dark-body {
  background: #0A0A0A;
  color: #FFFFFF;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-weight: 300;
}
.gallery-dark-section {
  padding: 4rem 0;
}
@media (min-width: 768px) {
  .gallery-dark-section {
    padding: 6rem 0;
  }
}
.gallery-dark-lightbox {
  position: fixed;
  inset: 0;
  background: rgba(10, 10, 10, 0.95);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 300ms ease-out;
  pointer-events: none;
}
.gallery-dark-lightbox.open {
  opacity: 1;
  pointer-events: auto;
}
.gallery-dark-lightbox img {
  max-height: 90vh;
  max-width: 90vw;
  object-fit: contain;
}
